class Solution {
  public int buttonWithLongestTime(int[][] events) {
    int bestIndex = events[0][0], bestTime = events[0][1];
    for (int i = 1; i < events.length; i++) {
      int time = events[i][1] - events[i - 1][1];
      if (time > bestTime || (time == bestTime && events[i][0] < bestIndex)) {
        bestTime = time;
        bestIndex = events[i][0];
      }
    }
    return bestIndex;
  }
}
